import{_t as e,it as t,n,rt as r}from"./chunks/framework.DmGhRbf7.js";var i=JSON.parse(`{"title":"Rename a plugin or theme","description":"","frontmatter":{},"headers":[],"relativePath":"renaming-projects.md","filePath":"renaming-projects.md"}`),a={name:`renaming-projects.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="rename-a-plugin-or-theme" tabindex="-1">Rename a plugin or theme <a class="header-anchor" href="#rename-a-plugin-or-theme" aria-label="Permalink to “Rename a plugin or theme”">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to “Overview”">​</a></h2><p>Replace the old identity with <strong>BCEW</strong> (British Columbia Extended Web) naming.</p><p>Do not open a pull request until the <strong>newly named BCEW Theme or Plugin</strong> is running on test.</p><p><strong>Search only the plugin/themes folder</strong>. Do not find-and-replace the whole monorepo.</p><p>Use your editor’s <strong>Find</strong> (Mac or Windows) in that folder. The ticket tells you what to search for. Common searches:</p><ul><li>The old slug (for example <code>design-system-wordpress-theme</code>, <code>wordpress-document-repository</code>)</li><li><code>design-system</code>, <code>design system</code>, <code>DSWP</code>, <code>dswp</code></li><li>The old display name from the ticket</li></ul><p>Replace with the new slug and display name from the ticket. Work through steps 2–5 in order — not one big find-and-replace.</p><h2 id="_1-rename-the-folder" tabindex="-1">1. Rename the folder <a class="header-anchor" href="#_1-rename-the-folder" aria-label="Permalink to “1. Rename the folder”">​</a></h2><p>Use <code>git mv</code>. Do not drag the folder in Finder.</p><p><strong>Plugin:</strong></p><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> plugins/</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">old-slu</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">g</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> plugins/</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">new-slu</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">g</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> plugins/</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">new-slu</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">g</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">old-slu</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">g</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> plugins/</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">new-slu</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">g</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">new-slu</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">g</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.php</span></span></code></pre></div><p><strong>Theme:</strong></p><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> themes/</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">old-slu</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">g</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> themes/</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">new-slu</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">g</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><p>Use the slugs from the ticket.</p><p><strong>Plugins with a JS app:</strong> also <code>git mv</code> folders that match the old slug (for example <code>assets/js/apps/&lt;old-slug&gt;/</code> → <code>assets/js/apps/&lt;new-slug&gt;/</code>) and update build paths in <code>package.json</code>.</p><h2 id="_2-change-these-in-this-project" tabindex="-1">2. Change these in this project <a class="header-anchor" href="#_2-change-these-in-this-project" aria-label="Permalink to “2. Change these in this project”">​</a></h2><p>After the folder rename, find the old name again inside <code>plugins/&lt;new-slug&gt;/</code> or <code>themes/&lt;new-slug&gt;/</code>.</p><table tabindex="0"><thead><tr><th>File</th><th>Change</th></tr></thead><tbody><tr><td><code>project.json</code></td><td><code>name</code>, <code>root</code>, <code>sourceRoot</code> → new slug; generator <code>slug</code> → new slug (themes)</td></tr><tr><td><code>composer.json</code></td><td><code>&quot;name&quot;</code> → <code>bcgov-plugin/&lt;new-slug&gt;</code> or <code>bcgov-theme/&lt;new-slug&gt;</code></td></tr><tr><td><code>package.json</code></td><td><code>name</code>, <code>homepage</code>, <code>repository.directory</code>, build script paths → new slug</td></tr><tr><td>Plugin header or <code>style.css</code></td><td><code>Plugin Name:</code> / <code>Theme Name:</code>, URI, <code>Text Domain:</code> → new names</td></tr><tr><td><code>theme.json</code></td><td><code>title</code>, <code>textDomain</code> → new names (if present)</td></tr><tr><td><code>.wp-env.json</code></td><td><code>wp plugin activate &lt;new-slug&gt;</code> or <code>wp theme activate &lt;new-slug&gt;</code></td></tr><tr><td>README and <code>docs/</code></td><td>old slug and old display name → new names</td></tr></tbody></table><h2 id="_3-update-php-css-and-js-names-where-safe" tabindex="-1">3. Update PHP, CSS, and JS names (where safe) <a class="header-anchor" href="#_3-update-php-css-and-js-names-where-safe" aria-label="Permalink to “3. Update PHP, CSS, and JS names (where safe)”">​</a></h2><p>Search again for the old slug in <code>.php</code>, <code>.js</code>, <code>.jsx</code>, <code>.ts</code>, <code>.tsx</code>, <code>.scss</code>, and <code>.css</code> files inside this project.</p><p><strong>For themes:</strong> Also check:</p><ul><li><code>Text Domain:</code> in <code>style.css</code> — leave unset if it is not currently set (do not introduce one just to rename)</li><li><code>textDomain</code> in <code>theme.json</code> — leave unset if it is not currently set</li></ul><p><strong>Change these together</strong> — if you rename a CSS class, update the matching rule in SCSS/CSS, the <code>className</code> in JS, and any HTML or PHP that outputs it in the same edit:</p><table tabindex="0"><thead><tr><th>Kind</th><th>Change</th></tr></thead><tbody><tr><td>CSS / SCSS classes</td><td>Old slug prefix → new slug (for example <code>.wordpress-document-repository</code> → <code>.bcew-document-repository</code>)</td></tr><tr><td>JS <code>className</code></td><td>Match the CSS change</td></tr><tr><td>PHP global functions</td><td>Rename <code>old_slug_*</code> functions to <code>new_slug_*</code>; update every <code>add_action</code> / <code>add_filter</code></td></tr><tr><td>Script and style handles</td><td>Old slug → new slug in <code>wp_enqueue_*</code> calls</td></tr><tr><td>DOM <code>id</code>s and app mount points</td><td>Old slug → new slug (for example <code>#bcew-document-repository-app</code>)</td></tr><tr><td>REST namespace, menu slugs, nonce keys</td><td>Old slug → new slug when they only identify this project in code</td></tr></tbody></table><p>See step 5 before changing any string that might already be saved on a live site.</p><h2 id="_4-change-two-repo-files" tabindex="-1">4. Change two repo files <a class="header-anchor" href="#_4-change-two-repo-files" aria-label="Permalink to “4. Change two repo files”">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>Change</th></tr></thead><tbody><tr><td><code>.github/labeler.yml</code></td><td>Rename the project key and path to <code>plugins/&lt;new-slug&gt;/**</code> or <code>themes/&lt;new-slug&gt;/**</code> (or add if new)</td></tr><tr><td><code>.github/workflows/tag.yml</code></td><td><strong>Add</strong> <code>&lt;new-slug&gt;</code> to the project dropdown (imported standalones were never listed here)</td></tr></tbody></table><p><strong>Important:</strong> Step 4 must be done <strong>before testing on the blog repo</strong> (step 7). The new slug must be in <code>tag.yml</code> or the release workflow will fail.</p><p><strong>For child themes:</strong> Also check <code>&lt;new-slug&gt;</code> for parent theme references that might need updating:</p><table tabindex="0"><thead><tr><th>File</th><th>Change</th></tr></thead><tbody><tr><td><code>style.css</code></td><td><code>Template:</code> → <code>&lt;new-slug&gt;</code> (if this theme is a child of <code>&lt;new-slug&gt;</code>)</td></tr><tr><td><code>.wp-env.json</code></td><td>parent path → <code>&quot;../../themes/&lt;new-slug&gt;&quot;</code> (if applicable)</td></tr></tbody></table><p><strong>For themes with template parts or block patterns:</strong> After you rename the folder and update <code>project.json</code>, also check these files:</p><table tabindex="0"><thead><tr><th>File</th><th>Change</th></tr></thead><tbody><tr><td>Template part <code>theme</code> attribute in <code>parts/*.html</code>, <code>templates/*.html</code></td><td>Update <code>&quot;theme&quot;:&quot;&lt;old-slug&gt;&quot;</code> → <code>&quot;theme&quot;:&quot;&lt;new-slug&gt;&quot;</code> <em>(the slug must match the active theme slug)</em></td></tr><tr><td>Pattern slug references in <code>patterns/*.php</code> and template files</td><td>Update <code>&quot;theme&quot;:&quot;&lt;old-slug&gt;&quot;</code> in <code>wp:pattern</code> references and template-part blocks to <code>&quot;theme&quot;:&quot;&lt;new-slug&gt;&quot;</code> <em>(the slug must match the active theme slug)</em></td></tr><tr><td>Screenshot/Playwright tests</td><td>If the theme has visual regression tests (e.g. <code>patterns.spec.js</code>), update the theme slug in test files. Pattern slugs themselves keep the old prefix (stored data).</td></tr></tbody></table><p>See step 5 before changing pattern or template slugs that might be saved on a live site.</p><h2 id="_5-do-not-change-stored-names" tabindex="-1">5. Do not change stored names <a class="header-anchor" href="#_5-do-not-change-stored-names" aria-label="Permalink to “5. Do not change stored names”">​</a></h2><p>Rename the <strong>package</strong> (folder, Composer name, plugin header). Do not rename <strong>data</strong> WordPress already saved.</p><p><strong>One question before you change a string:</strong> would a site that already runs the old plugin/theme break if the database still has the old value? If yes, leave it — even when it still says design system, DSWP, or the old slug.</p><table tabindex="0"><thead><tr><th>You find it in…</th><th>Leave it alone</th></tr></thead><tbody><tr><td><code>get_option</code>, <code>update_option</code>, <code>register_setting</code></td><td>Option keys and settings group names</td></tr><tr><td><code>get_post_meta</code>, <code>update_post_meta</code></td><td>Meta keys</td></tr><tr><td>First argument to <code>do_action</code>, <code>add_action</code>, <code>apply_filters</code></td><td>Hook names</td></tr><tr><td><code>register_post_type</code>, <code>register_taxonomy</code></td><td>Post type and taxonomy slugs</td></tr><tr><td><code>block.json</code>, block patterns, <code>theme.json</code> colour presets</td><td>Block names, pattern slugs, preset slugs</td></tr><tr><td>Post content, patterns, or upload folder paths</td><td>CSS classes in saved HTML, media URL paths</td></tr><tr><td><code>__( &#39;…&#39;, &#39;text-domain&#39; )</code> owned by another package</td><td>Shared text domains (for example <code>bcgov-design-system</code>)</td></tr><tr><td>Composer <code>autoload</code> <code>psr-4</code></td><td>PHP namespace (unless the ticket says to change it)</td></tr><tr><td>Template part names (<code>wp:template-part</code> <code>name</code> field)</td><td>Template part slugs (internal identifiers)</td></tr><tr><td>Pattern slug prefix in headers and pattern references</td><td>Prefixed pattern slugs (e.g. <code>&lt;old-slug&gt;/pattern-name</code>)</td></tr></tbody></table><p><strong>For themes with template parts:</strong> The <code>theme</code> attribute in <code>wp:template-part</code> blocks <em>must</em> match the active theme slug. Change the <code>theme</code> attribute to the new slug, but do not change the <code>slug</code> (name) of the template part itself.</p><p><strong>For themes with block patterns:</strong> Prefixed pattern slugs (e.g. <code>&lt;old-slug&gt;/pattern-name</code>) are stored data in blocks. Do not change the prefix — it keeps patterns accessible when the theme is updated. Only change the <code>theme</code> attribute in template-part references to match the new theme slug.</p><p>When in doubt, leave it and note it on the ticket.</p><h2 id="_6-test-locally" tabindex="-1">6. Test locally <a class="header-anchor" href="#_6-test-locally" aria-label="Permalink to “6. Test locally”">​</a></h2><p>From the monorepo root (use the new slug from the ticket):</p><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">new-slu</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">g</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">:build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">new-slu</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">g</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">:wp-env-start</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lint</span></span></code></pre></div><p>Run this project’s tests. Click through admin, the front end, and the main feature.</p><p><strong>For themes with screenshot tests:</strong> If snapshots render the theme slug (for example, the site title), regenerate them:</p><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">new-slu</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">g</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">:test-screenshot-generate</span></span></code></pre></div><p>Review the diff — only snapshots that display the slug should change. Pure renames and path changes should be handled by git.</p><p><strong>Final sweep:</strong> Check that <code>git status</code> shows renames (<code>R</code>), not delete+add, for unchanged files. This confirms <code>git mv</code> worked correctly.</p><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">new-slu</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">g</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">:wp-env-stop</span></span></code></pre></div><h2 id="_7-test-on-test-blog-repo-—-before-the-pr" tabindex="-1">7. Test on test (blog repo) — before the PR <a class="header-anchor" href="#_7-test-on-test-blog-repo-—-before-the-pr" aria-label="Permalink to “7. Test on test (blog repo) — before the PR”">​</a></h2><p>Test site: <code>test.vanity.blog.gov.bc.ca</code></p><p>Blog repo: <a href="https://bitbucket.org/bc-gov/blog_gov_bc_ca" target="_blank" rel="noreferrer">blog_gov_bc_ca</a> on Bitbucket (<code>bc-gov/blog_gov_bc_ca</code>). Plugins and themes are Composer packages in the root <code>composer.json</code>. They install to <code>web/app/plugins/</code> and <code>web/app/themes/</code>. The <code>https://bcgov.github.io/bcew-monorepo</code> repository is already in <code>composer.json</code>. Both the <strong>old</strong> and <strong>new</strong> package can be in <code>require</code> at the same time.</p><p><strong>Step 4 must be done first</strong> — <code>&lt;new-slug&gt;</code> has to be in <code>.github/workflows/tag.yml</code> or the release workflow cannot run.</p><h3 id="monorepo-publish-a-pre-release-from-your-branch" tabindex="-1">Monorepo: publish a pre-release from your branch <a class="header-anchor" href="#monorepo-publish-a-pre-release-from-your-branch" aria-label="Permalink to “Monorepo: publish a pre-release from your branch”">​</a></h3><ol><li>Push your monorepo branch.</li><li>GitHub → <strong>bcew-monorepo → Actions → Release Subproject and Update packages.json → Run workflow</strong>.</li><li><strong>Use workflow from:</strong> your rename feature branch — not <code>main</code>. The rename is not merged yet, so <code>main</code> does not have <code>&lt;new-slug&gt;</code> in <code>tag.yml</code> and would release the wrong project or fail.</li><li><strong>Project to release:</strong> <code>&lt;new-slug&gt;</code></li><li>Leave <strong>Alpha</strong> ticked. A new name has no <code>{project}/v*</code> tags, so the workflow releases <code>1.0.0-alpha.1</code>. Each run will push a <code>chore(release): publish</code> commit with version bumps to your branch, so use <code>git pull --rebase</code> before pushing later changes.</li><li>Run it. Wait for green. The log prints the version. This publishes a zip to GitHub Releases and adds <code>bcgov-plugin/&lt;new-slug&gt;</code> or <code>bcgov-theme/&lt;new-slug&gt;</code> to <a href="https://bcgov.github.io/bcew-monorepo/" target="_blank" rel="noreferrer">packages.json</a>.</li></ol><h3 id="blog-repo-install-the-pre-release-on-test" tabindex="-1">Blog repo: install the pre-release on test <a class="header-anchor" href="#blog-repo-install-the-pre-release-on-test" aria-label="Permalink to “Blog repo: install the pre-release on test”">​</a></h3><p><strong>1.</strong> Clone <a href="https://bitbucket.org/bc-gov/blog_gov_bc_ca" target="_blank" rel="noreferrer">blog_gov_bc_ca</a>. Branch from <code>development</code>.</p><p><strong>2.</strong> In <code>composer.json</code>, add the <strong>new</strong> package at the version the workflow printed (monorepo step 6). Keep the <strong>old</strong> package in <code>require</code>.</p><div class="language-json"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;bcgov-plugin/&lt;old-slug&gt;&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&lt;existing-version&gt;&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;bcgov-plugin/&lt;new-slug&gt;&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;1.0.0-alpha.1&quot;</span></span></code></pre></div><p>For a theme, use <code>bcgov-theme/&lt;new-slug&gt;</code> instead of <code>bcgov-plugin/&lt;new-slug&gt;</code>.</p><p><strong>3.</strong> Update the lock file and commit both files:</p><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">composer</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bcgov-plugin/</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">new-slu</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">g</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">   # or bcgov-theme/&lt;new-slug&gt; for themes</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> composer.json</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> composer.lock</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> commit</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Add &lt;new-slug&gt; pre-release for rename testing&quot;</span></span></code></pre></div><p><strong>4.</strong> Push to <code>development</code> (or open a PR to <code>development</code> and merge). Wait for deploy to test.</p><p><strong>5.</strong> Log in to <code>test.vanity.blog.gov.bc.ca/wp-admin</code>.</p><p><strong>Theme only:</strong> Before activating the new theme, first network-enable it at <a href="https://test.vanity.blog.gov.bc.ca/wp-admin/network/themes.php" target="_blank" rel="noreferrer">Network Admin → Themes</a>. Until it is network-enabled, it cannot be selected in a site&#39;s wp-admin on test.</p><p><strong>6.</strong> Activate the new name and deactivate the old:</p><ul><li><strong>Plugin:</strong> Plugins → deactivate <code>&lt;old-slug&gt;</code> → activate <code>&lt;new-slug&gt;</code></li><li><strong>Theme:</strong> Appearance → Themes → deactivate <code>&lt;old-slug&gt;</code> → activate <code>&lt;new-slug&gt;</code></li></ul><p>The old name must be <strong>off</strong> and the new name <strong>on</strong> for testing.</p><p><strong>7.</strong> Click through admin, front end, and the main feature — same checks as step 6 (locally). For themes, verify:</p><ul><li>Admin interface loads without errors</li><li>Front page, pages, and single entries render correctly</li><li>Search results, 404 page, and project-specific templates display properly</li><li>Navigation, header, footer, and page layouts are correct</li><li>Any theme-specific features (patterns, parts, custom templates) work as expected</li></ul><p><strong>8.</strong> Record the test result in the monorepo PR:</p><ul><li>Confirm the new package (<code>&lt;new-slug&gt;</code>) is active on TEST</li><li>Record which features were tested and whether any issues were found</li><li>If no issues were found, explicitly state that</li></ul><p>Then open the monorepo PR.</p><h2 id="_8-open-the-pr" tabindex="-1">8. Open the PR <a class="header-anchor" href="#_8-open-the-pr" aria-label="Permalink to “8. Open the PR”">​</a></h2><p><strong>Do not open the PR until test runs the new slug</strong> (step 7).</p><p>When opening, include in the PR body:</p><ul><li>Old and new names/slugs</li><li>Summary of what was changed (folder rename, metadata, pattern slug references, etc.)</li><li>What was intentionally left unchanged (pattern slug prefixes, PHP namespaces, etc.)</li><li>If a theme: note about regenerated screenshot snapshots (only display-name snapshots should change)</li><li>TEST validation results: what was tested and any issues found (or explicit statement that none were found)</li><li>Commit message reference: note if the bot added version/CHANGELOG commits (this is normal)</li></ul><p><strong>Plugin example title:</strong></p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>refactor(plugin-name): rename to new name</span></span></code></pre></div><p><strong>Theme example title:</strong></p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>refactor(theme-name): rename theme to New Display Name</span></span></code></pre></div><h2 id="_9-production-later" tabindex="-1">9. Production (later) <a class="header-anchor" href="#_9-production-later" aria-label="Permalink to “9. Production (later)”">​</a></h2><p>Same as test: both names exist at first. Disable old, enable new, click through. Remove the old name from deploy only when you are sure.</p>`,84)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};